const concepts={
 a:{name:'Забота по шагам',short:'Следующий шаг',thesis:'Приложение подсказывает одно полезное действие в каждый момент.',logic:'Начинаем с ближайшего визита или понятной задачи. Во время записи показываем только текущий выбор; итог и последствия — перед подтверждением.',benefits:['Минимум решений на одном экране','Легко вернуться к незавершённому действию','Удобно редким посетителям и новичкам'],trade:'Для сравнения многих вариантов потребуется больше переходов.'},
 b:{name:'Найти своё время',short:'Поиск времени',thesis:'Сначала ищем удобный момент, затем выбираем лучший вариант.',logic:'Постоянные фильтры «когда, какая услуга, где» ведут к списку конкретных доступных вариантов. Рабочий кабинет организован вокруг временной сетки и фильтров.',benefits:['Быстрый ответ на вопрос «когда свободно?»','Можно сравнить несколько вариантов сразу','Удобно клиентам с жёстким расписанием'],trade:'Плотный список требует аккуратной настройки фильтров.'},
 c:{name:'Мои места',short:'Салон как дом',thesis:'Все отношения с салоном живут в одном понятном месте.',logic:'Сначала выбираем салон. Внутри него вместе лежат услуги, мои визиты, награды и предложения; рабочие задачи тоже сохраняют контекст конкретного салона.',benefits:['Салон и его люди запоминаются как единое место','Просто найти свою награду и историю','Подходит постоянным клиентам'],trade:'Для сравнения разных салонов нужен выход на уровень выше.'},
 bc:{name:'Время и места',short:'Фильтры + карточки',thesis:'Сначала задаём удобные условия, затем выбираем салон из понятных карточек.',logic:'Верхняя панель уточняет услугу, день и время. Ниже знакомые и новые салоны показаны карточками с ближайшим окном, ценой и личным контекстом. После выбора салона фильтры остаются видимыми.',benefits:['Быстрый поиск без потери знакомого салона','Карточки дают достаточно контекста для выбора','На телефоне и компьютере маршрут остаётся узнаваемым'],trade:'Нужно внимательно управлять пустыми результатами при узких фильтрах.'}
};
const groups={
 'Клиент · выбор и запись':[['home','Главная'],['discover','Найти салон'],['salon','Витрина салона'],['service','Услуга'],['slots','Время и мастер'],['quote','Итог перед записью'],['confirmed','Подтверждено'],['bookings','Мои записи'],['booking','Карточка записи'],['reschedule','Обычный перенос'],['cancel','Отмена записи'],['cancelled','Запись отменена'],['history','История'],['review','Оценка мастера']],
 'Клиент · возможности':[['waitlist','Запросы ожидания'],['waitForm','Предпочтения окна'],['requestSaved','Запрос создан'],['offer','Предложение окна'],['offerResult','Результат предложения'],['loyalty','Награды'],['offers','Купоны и акции'],['promo','Условия акции'],['events','События'],['profile','Уведомления и профиль']],
 'Салон · день':[['workHome','Рабочий обзор'],['calendar','Календарь'],['workBooking','Запись клиента'],['newBooking','Ручная запись'],['customers','CRM'],['customer','Карточка клиента'],['live','Живое окно'],['stop','Остановить окно'],['masterDay','Календарь мастера'],['masterVisit','Исход визита']],
 'Салон · управление':[['catalog','Услуги и мастера'],['schedule','График'],['analytics','Статистика'],['programs','Программы лояльности'],['partners','Партнёрства'],['workPromos','Акции'],['settings','Настройки и витрина'],['access','Сотрудники и доступ'],['audit','Журнал действий'],['createSalon','Создать салон'],['invite','Приглашение'],['role','Выбор кабинета']]
};
const screens=Object.fromEntries(Object.values(groups).flat().map(([id,title])=>[id,title]));
const client=new Set(Object.values(groups).slice(0,2).flat().map(x=>x[0]));const master=new Set(['masterDay','masterVisit','role']);
const state={concept:'c',theme:localStorage.getItem('ryadom-theme')==='dark'?'dark':'light',screen:'home',role:'client',view:'phone',history:[],service:'Стрижка и укладка',duration:60,price:2400,staff:'Анна',slot:'15:00',date:'29 сентября',period:'После 12:00',searchService:'Любая',benefit:'none',salon:'Линия',booking:{id:'1042',date:'2 октября',time:'16:00',service:'Стрижка и укладка',staff:'Анна',price:2400,salon:'Линия'},linked:false,request:false,offerResult:'success',windowStopped:false,query:'',section:'services',consent:false,noSlots:false,masterYear:2026,masterMonth:8,masterDate:29,ownerYear:2026,ownerMonth:8,ownerDate:29,ownerStaff:'all',ownerStaffOpen:false,ownerStaffQuery:''};
const app=document.querySelector('#app');
const h=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const cash=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const button=(label,to,kind='primary',extra='')=>`<button class="btn ${kind}" data-go="${to}" ${extra}>${label}</button>`;
const act=(label,action,kind='secondary',value='')=>`<button class="btn ${kind}" data-action="${action}" data-value="${h(value)}">${label}</button>`;
const card=(label,detail,to,over='')=>`<div class="paper"><button class="touch" data-go="${to}"><div class="touch-row"><div>${over?`<span class="kicker">${over}</span><br>`:''}<strong>${label}</strong><div class="mini">${detail}</div></div><span class="arrow">›</span></div></button></div>`;
const note=(title,text,type='soft')=>`<div class="paper ${type}"><strong>${title}</strong><div class="mini" style="margin-top:5px">${text}</div></div>`;
const chips=(items,selected,action)=>`<div class="chips">${items.map(([label,value])=>`<button class="${selected===value?'sel':''}" data-action="${action}" data-value="${h(value)}">${label}</button>`).join('')}</div>`;
const meta=rows=>`<dl class="meta-list">${rows.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl>`;
const heading=(tag,title,sub='')=>`<div class="home-line">${tag}</div><h1>${title}</h1>${sub?`<p class="sub">${sub}</p>`:''}`;
const sep='<hr class="divider">';
const art=(title,small)=>`<div class="art"><span>${title}</span><small>${small}</small></div>`;
const niceDate=v=>new Date(v+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
const inSalon=()=>state.salon==='Линия'?'Линии':state.salon==='Точка'?'Точке':'Клевере';
const workRole=()=>state.role==='master'?'Мастер':state.role==='admin'?'Администратор':'Владелец';
const workRoot=()=>state.role==='master'?'masterDay':state.role==='owner'?'calendar':'workHome';
const portalTabs=()=>`<div class="salon-tabs"><button class="${state.section==='services'?'sel':''}" data-action="section" data-value="services">Услуги</button><button class="${state.section==='visits'?'sel':''}" data-action="section" data-value="visits">Визиты</button><button class="${state.section==='perks'?'sel':''}" data-action="section" data-value="perks">Бонусы</button></div>`;
const hybridSalons=[
 {name:'Линия',kind:'Студия волос',address:'ул. Лесная, 12',service:'Стрижка и укладка',staff:'Анна',price:2400,time:'15:00',reward:'Ваша награда доступна',mark:'ЗНАКОМОЕ МЕСТО'},
 {name:'Точка',kind:'Студия ногтей',address:'ул. Садовая, 8',service:'Маникюр',staff:'Елена',price:1800,time:'16:30',reward:'Вы были здесь 2 раза',mark:'РЯДОМ С ВАМИ'},
 {name:'Клевер',kind:'Уход и массаж',address:'ул. Мира, 17',service:'Массаж',staff:'Ольга',price:2800,time:'18:00',reward:'Новое место для вас',mark:'ПОПРОБОВАТЬ НОВОЕ'}
];
const salonKeywords={Линия:'волосы парикмахерская стрижка укладка стилист',Точка:'ногти маникюр педикюр нейл',Клевер:'уход массаж спа релакс'};
function cSearchMatches(){let words=state.query.toLocaleLowerCase('ru-RU').replaceAll('ё','е').trim().split(/\s+/).filter(Boolean);return hybridSalons.filter(s=>{let hay=[s.name,s.kind,s.address,s.service,s.staff,salonKeywords[s.name]].join(' ').toLocaleLowerCase('ru-RU').replaceAll('ё','е');return words.every(w=>hay.includes(w))})}
function cPlaceCard(s){let tone=s.name==='Линия'?'hair':s.name==='Точка'?'nails':'care';return `<article class="c-place-card"><div class="c-place-art ${tone}"><span>${h(s.name)}</span><small>${h(s.kind)}</small></div><div class="c-place-body"><span class="kicker">${h(s.mark)}</span><h3>${h(s.name)}</h3><p class="mini">${h(s.address)} · ★ 4,9</p><p class="c-place-service">${h(s.service)} · от ${cash(s.price)}</p><div class="c-place-footer"><span>${h(s.reward)}</span><button data-go="salon" data-salon="${h(s.name)}">Открыть место →</button></div></div></article>`}
function cSearchResults(){if(!state.query.trim())return '';let matches=cSearchMatches();return `<div class="c-search-results"><div class="c-results-heading"><h2>Результаты поиска</h2><span class="mini">${matches.length} ${matches.length===1?'место':matches.length>1&&matches.length<5?'места':'мест'}</span></div>${matches.length?`<div class="c-place-list">${matches.map(cPlaceCard).join('')}</div>`:`<div class="paper c-empty"><strong>Такого места пока не нашли</strong><p class="mini">Попробуйте название салона, услугу или слово «волосы», «ногти», «массаж».</p><button data-action="clearSearch">Очистить поиск</button></div>`}</div>`}
function cSearchBox(){return `<div class="c-search-box"><label for="placeSearch">Найти салон или услугу</label><div class="c-search-field"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.3"></circle><path d="m15.5 15.5 5 5"></path></svg><input id="placeSearch" data-place-search type="search" placeholder="Например, маникюр или Линия" value="${h(state.query)}" autocomplete="off" aria-label="Поиск салона или услуги"></div><p class="mini">Поиск по названию, услуге и ключевым словам</p></div>`}
function cHome(){let s=hybridSalons[0];return heading('МОИ МЕСТА','Хорошо, что вы здесь','Знакомые салоны, визиты и награды всегда под рукой.')+`<section class="c-feature"><span class="kicker">ВАШЕ МЕСТО</span><h2>${s.name}</h2><p>${s.kind} · ${s.address}</p><div class="c-feature-visit"><span>Следующий визит</span><strong>${h(state.booking.date)} · ${h(state.booking.time)}</strong></div><button data-go="salon" data-salon="Линия">Открыть «Линию» →</button></section>${cSearchBox()}<div class="c-results-slot">${cSearchResults()}</div>`}
function cDiscover(){return heading('ПОИСК МЕСТА','Найдите своё место','Ищите по названию салона, услуге или тому, что хотите сделать.')+cSearchBox()+`<div class="c-results-slot">${cSearchResults()}</div>`}
function cBottom(){const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',bookings:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-12 6 2 2 4-4"/>',loyalty:'<rect x="3" y="10" width="18" height="11" rx="1"/><path d="M2 7h20v4H2zm10 0v14M12 7c-3.5 0-5.5-.7-5.5-2.5A2.5 2.5 0 0 1 9 2c2 0 3 2.3 3 5Zm0 0c3.5 0 5.5-.7 5.5-2.5A2.5 2.5 0 0 0 15 2c-2 0-3 2.3-3 5Z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2z"/>'};let links=[['Мои места','home'],['Записи','bookings'],['Бонусы','loyalty'],['Профиль','profile']];return `<nav class="bottom c-bottom" aria-label="Основная навигация">${links.map(([label,to])=>{let selected=state.screen===to||(to==='home'&&['salon','discover','service','slots','quote'].includes(state.screen))||(to==='bookings'&&['booking','history','reschedule'].includes(state.screen));return `<button data-go="${to}" class="${selected?'active':''}" ${selected?'aria-current="page"':''}><span class="nav-symbol"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[to]}</svg></span><span>${label}</span></button>`}).join('')}</nav>`}
function cSalon(){let s=hybridSalons.find(x=>x.name===state.salon)||hybridSalons[0],isLine=s.name==='Линия',hasVisit=state.booking.salon===s.name;return `<div class="c-salon-header"><span class="kicker">${isLine?'ВАШЕ ЗНАКОМОЕ МЕСТО':'МЕСТО РЯДОМ'}</span><h1>${h(s.name)}</h1><p class="sub">${h(s.kind)} · ${h(s.address)}</p></div><div class="c-salon-art ${isLine?'hair':s.name==='Точка'?'nails':'care'}"><strong>${isLine?'Хорошо, что вы вернулись':'Место для вашего времени'}</strong><span>★ 4,9 · ежедневно 09:00–21:00</span></div>${portalTabs()}${state.section==='visits'?(hasVisit?card('Ваш следующий визит',`${h(state.booking.date)} · ${h(state.booking.time)} · ${h(state.booking.staff)}`,'booking'):'')+card('История визитов',isLine?'8 завершённых визитов':s.name==='Точка'?'2 завершённых визита':'Пока нет визитов','history'):state.section==='perks'?(isLine?card('Бесплатное посещение','Стрижка и укладка · награда доступна','loyalty')+card('Акции «Линии»','Сроки и условия','offers'):note('Бонусы этого места','После визитов здесь появятся доступные награды.')):`<h2>Услуги</h2>${card(s.service,`60 минут · ${cash(s.price)} · ${s.staff}`,'service')}${isLine?card('Укладка','45 минут · 1 600 ₽ · Мария','service'):''}${hasVisit?card('Ваш следующий визит',`${h(state.booking.date)} · ${h(state.booking.time)}`,'booking'):''}`}${button('Найти другое место','discover','secondary')}`}
function hybridFilters(){return `<section class="hybrid-filters" aria-label="Параметры поиска"><div class="hybrid-filter-title"><span class="kicker">ПАРАМЕТРЫ ПОИСКА</span><strong>Когда вам удобно?</strong></div><div class="hybrid-filter-grid"><div><span class="filter-label">Услуга</span>${chips([['Любая','Любая'],['Стрижка','Стрижка'],['Маникюр','Маникюр'],['Массаж','Массаж']],state.searchService,'searchService')}</div><div><span class="filter-label">День</span>${chips([['Сегодня','Сегодня'],['Завтра','Завтра'],['29 сен','29 сентября'],['30 сен','30 сентября']],state.date,'date')}</div><div><span class="filter-label">Время</span>${chips([['Любое','Любое'],['Утром','Утро'],['После 12','После 12:00'],['Вечером','Вечер']],state.period,'period')}</div></div>${button('Показать подходящие места','discover')}</section>`}
function hybridPlaceCard(s){let time=state.period==='Утро'?'10:00':state.period==='Вечер'?s.name==='Линия'?'18:00':s.name==='Точка'?'19:00':'20:00':s.time;return `<article class="place-card"><div class="place-card-art ${s.name==='Линия'?'hair':s.name==='Точка'?'nails':'care'}"><span>${s.name}</span><small>${s.kind}</small></div><div class="place-card-body"><span class="kicker">${s.mark}</span><h3>${s.name}</h3><p class="mini">${s.address} · ★ 4,9</p><div class="place-availability"><span><strong>${h(state.date)} · ${time}</strong><small>${s.service} · ${s.staff}</small></span><strong>${cash(s.price)}</strong></div><div class="place-card-foot"><span>${s.reward}</span><button data-go="quote" data-salon="${s.name}" data-service="${s.service}" data-staff="${s.staff}" data-price="${s.price}" data-slot="${time}">Выбрать ${time}</button><button class="text-link" data-go="salon" data-salon="${s.name}">О салоне →</button></div></div></article>`}
function hybridHome(){return heading('ВРЕМЯ И МЕСТА','Найдём время в хорошем месте','Сначала задайте удобные условия. Затем посмотрите салоны, людей и цену в карточках.')+hybridFilters()+`<div class="hybrid-section-head"><div><span class="kicker">ДЛЯ ВАС</span><h2>Места, которые вам подходят</h2></div><span class="mini">Знакомые и новые рядом</span></div><div class="place-list">${hybridSalons.map(hybridPlaceCard).join('')}</div>${card('Мои ближайшие визиты',`${h(state.booking.date)} · ${h(state.booking.time)}`,'bookings')}`}
function hybridDiscover(){let matches=hybridSalons.filter(s=>state.searchService==='Любая'||s.service.toLowerCase().includes(state.searchService.toLowerCase()));return heading('ПОИСК ПО МЕСТАМ','Подходящие салоны','Условия поиска остаются сверху, а каждое место показывает конкретное свободное время.')+hybridFilters()+`<div class="hybrid-section-head"><h2>${matches.length} ${matches.length===1?'место':'места'} для вас</h2><span class="mini">${h(state.date)} · ${h(state.period)}</span></div><div class="place-list">${matches.map(hybridPlaceCard).join('')}</div>${note('Не нашли подходящее время?','Оставьте пожелания. Запрос не создаёт запись и не удерживает слот.')}${button('Сообщить об освободившемся времени','waitForm','secondary')}`}
function hybridSalon(){let s=hybridSalons.find(x=>x.name===state.salon)||hybridSalons[0];return `<div class="hybrid-search-summary"><span>Поиск: ${h(state.searchService)} · ${h(state.date)} · ${h(state.period)}</span><button data-go="home">Изменить</button></div>${heading('МОЁ МЕСТО / '+s.name.toUpperCase(),s.name,`${s.kind} · ${s.address}`)}<div class="place-card-art hero ${s.name==='Линия'?'hair':s.name==='Точка'?'nails':'care'}"><span>Хорошо, что вы здесь</span><small>${s.kind} · знакомое место</small></div>${portalTabs()}${state.section==='visits'?card('Ваш следующий визит',`${h(state.booking.date)} · ${h(state.booking.time)} · ${h(state.booking.staff)}`,'booking')+card('История визитов','Все завершённые посещения','history'):state.section==='perks'?card('Ваша награда','Посмотрите доступную выгоду','loyalty')+card('Акции этого места','Сроки и условия','offers'):`<h2>Услуги и ближайшее время</h2>${card(s.service,`60 минут · ${cash(s.price)} · ${s.staff}`,'service')}${hybridPlaceCard(s)}`}`}
function hybridSlots(){return heading('ВРЕМЯ В «'+inSalon().toUpperCase()+'»','Выберите удобный момент',`${h(state.service)} · ${h(state.duration)} минут · ${h(state.staff)}`)+`<div class="hybrid-search-summary"><span>${h(state.date)} · ${h(state.period)}</span><button data-go="home">Изменить поиск</button></div><h2>День</h2>${chips([['29 сен','29 сентября'],['30 сен','30 сентября'],['1 окт','1 октября']],state.date,'date')}<h2>Свободное время</h2>${state.noSlots?note('Пока нет подходящего времени','Выберите другой день или оставьте запрос.','warn'):`<div class="time-grid">${['12:00','15:00','16:30','18:00'].map(t=>`<button class="${state.slot===t?'sel':''}" data-action="slot" data-value="${t}">${t}</button>`).join('')}</div>${button('Проверить запись','quote')}`}${act(state.noSlots?'Показать варианты':'Показать состояние без слотов','toggleSlots','ghost')}${button('Сообщить об освободившемся времени','waitForm','secondary')}`}
function home(){const c=state.concept;if(c==='c')return cHome();if(c==='bc')return hybridHome();if(c==='a')return heading('Рядом · для вас','Добрый день, Анна','Мы собрали важное на сегодня.')+`<div class="task-hero"><span class="kicker">Ближайшее действие</span><div class="big">${state.booking.cancelled?'Выберите время для себя':'Ваш визит уже скоро'}</div><p class="sub" style="margin:6px 0">${state.booking.cancelled?'Подберём удобный визит':`${h(state.booking.date)}, ${h(state.booking.time)} · ${h(state.booking.salon||'Линия')} · ${h(state.booking.staff)}`}</p>${button(state.booking.cancelled?'Выбрать время':'Посмотреть запись',state.booking.cancelled?'discover':'booking')}</div>`+card('Хочу записаться','Начнём с услуги и салона','discover','ВЫБРАТЬ НОВЫЙ ВИЗИТ')+card('Есть свободное окно','Предложение действует до 12:10','offer','ЖИВОЕ ОКНО')+`<h2>Для вас</h2>`+card('Награда уже доступна','Один бесплатный визит · Линия','loyalty')+card('События и напоминания','1 новое событие','events');
 if(c==='b')return heading('Поиск · сразу к делу','Когда вам удобно?','Укажите время и сравните реальные варианты.')+`<label for="q">Какая услуга?</label><div class="search-input"><span>⌕</span><input id="q" placeholder="Например, стрижка" value="${h(state.query)}"></div><label>В какой день?</label>${chips([['Сегодня','Сегодня'],['Завтра','Завтра'],['29 сен','29 сентября'],['30 сен','30 сентября']],state.date,'date')}<label>После какого времени?</label>${chips([['Любое','Любое'],['Утро','Утро'],['После 12:00','После 12:00'],['Вечер','Вечер']],'После 12:00','period')}${button('Показать свободное время','discover')}<h2>Рядом с вами</h2>${card('15:00 · Линия','Стрижка и укладка · Анна · 2 400 ₽','quote','29 СЕНТЯБРЯ')}${card('16:30 · Точка','Маникюр · Елена · 1 800 ₽','quote')}`;
 return heading('Мои места','Салоны, куда хочется вернуться','Записи, люди и награды — рядом с каждым салоном.')+`<div class="salon-portal"><span class="kicker">МЕСТО, КОТОРОЕ ВЫ ЗНАЕТЕ</span><h1>Линия</h1><p class="sub">Студия волос · ул. Лесная, 12</p>${button('Открыть моё место','salon')}</div>${art('Время для себя','Знакомый мастер. Любимое место.')}<h2>Другие места</h2>${card('Точка','Маникюр · ул. Садовая, 8','salon')}${card('Мои визиты','Ближайший — 2 октября в 16:00','bookings')}${card('Новые предложения','Купоны и акции для вас','offers')}`}
function discover(){if(state.concept==='c')return cDiscover();if(state.concept==='bc')return hybridDiscover();if(state.concept==='b')return heading('Подходящие варианты','Свободно после 12:00','Сравните время, мастера и итоговую цену.')+`<div class="filter-band"><span class="kicker">Ваш поиск</span><p class="sub" style="margin:5px 0">29 сентября · стрижка · после 12:00</p>${act('Изменить фильтры','toHome','ghost')}</div>${card('15:00 · Анна','Линия · стрижка и укладка · 2 400 ₽','quote','БЛИЖЕ ВСЕГО')}${card('16:30 · Мария','Линия · стрижка и укладка · 2 400 ₽','quote')}${card('17:00 · Елена','Точка · маникюр · 1 800 ₽','quote')}${note('Не нашли удобного?','Оставьте условия. Мы сообщим, если освободится совместимое время.')}${button('Сообщить об освободившемся времени','waitForm','secondary')}`;
 return heading('Выберите место','Салоны рядом с вами',state.concept==='a'?'Можно начать со знакомого места или найти новое.':'Сначала выберите салон. У каждого — свои услуги и награды.')+`<label for="q">Поиск по названию</label><input id="q" placeholder="Название салона" value="${h(state.query)}">${card('Линия','Студия волос · ул. Лесная, 12 · ★ 4,9','salon','ВАШЕ ЛЮБИМОЕ МЕСТО')}${card('Точка','Студия ногтей · ул. Садовая, 8','salon')}${card('Клевер','Уход и массаж · ул. Мира, 17','salon')}`}
function salon(){if(state.concept==='c')return cSalon();if(state.concept==='bc')return hybridSalon();const name=h(state.salon),other=state.salon!=='Линия',kind=state.salon==='Точка'?'Студия ногтей':'Уход и массаж',address=state.salon==='Точка'?'ул. Садовая, 8':'ул. Мира, 17';if(other)return heading(`${name} · ${kind}`,'Место рядом с вами',`${address} · ежедневно 09:00–21:00`)+art('Время для себя',`${kind} · ${address}`)+`<h2>Услуги</h2>`+card(state.salon==='Точка'?'Маникюр':'Массаж',state.salon==='Точка'?'60 минут · 1 800 ₽':'60 минут · 2 800 ₽','service')+card('Все мои записи','Визиты в разных салонах','bookings');if(state.concept==='c')return `<div class="salon-header">МОЁ МЕСТО / ЛИНИЯ</div>${art('Хорошо, что вы вернулись','Студия волос · ул. Лесная, 12')}${portalTabs()}${state.section==='visits'?card('Ваш следующий визит',`${h(state.booking.date)}, ${h(state.booking.time)} · ${h(state.booking.staff)}`,'booking')+card('История в «Линии»','8 завершённых визитов','history'):state.section==='perks'?card('Бесплатное посещение','Стрижка и укладка · награда доступна','loyalty')+card('Акции «Линии»','Сроки и условия','offers'):heading('УСЛУГИ','Что хотите сделать?')+card('Стрижка и укладка','60 мин · от 2 400 ₽','service')+card('Укладка','45 мин · от 1 600 ₽','service')+card('Мастера «Линии»','Анна и Мария · выберите человека','slots')}${note('Всё в одном месте','Ваши записи и награды в «Линии» остаются здесь.')}`;
 return heading('Линия · студия волос','Место, где вас знают','ул. Лесная, 12 · ежедневно 09:00–21:00')+art('Забота в вашем ритме','Анна и Мария · рядом с домом')+`<h2>Услуги</h2>`+card('Стрижка и укладка','60 минут · 2 400 ₽','service')+card('Укладка','45 минут · 1 600 ₽','service')+card('Мои визиты в «Линии»','Ближайший: 2 октября','bookings')}
function service(){return heading(state.concept==='b'?'УСЛУГА / ФИЛЬТР':`${h(state.salon).toUpperCase()} / УСЛУГА`,state.service,'Понятная цена и длительность до выбора времени.')+art(state.service,'Для вашего хорошего дня')+meta([['Длительность',state.duration+' минут'],['Стоимость',cash(state.price)],['Мастера',state.salon==='Линия'?'Анна и Мария':state.staff],['Оплата','После визита в салоне']])+`<h2>${state.concept==='b'?'Доступные варианты':'Что дальше?'}</h2>`+(state.concept==='a'?note('Шаг 1 из 3','Далее выберите мастера и время; перед записью проверите итог.'):'')+button(state.concept==='b'?'Смотреть свободное время':'Выбрать время и мастера','slots')+button('Если удобного времени нет','waitForm','secondary')}
function slots(){if(state.concept==='bc')return hybridSlots();let top=heading('ВЫБОР ВРЕМЕНИ',state.concept==='a'?'Когда вам удобно?':state.concept==='b'?'Свободные окна':`Время в «${inSalon()}»`,state.service+' · '+state.duration+' минут');let steps=state.concept==='a'?'<div class="step-head"><i class="on"></i><i class="on"></i><i></i></div>':'';let m=state.concept==='b'?'Время показано для всех мастеров. Выберите вариант:':state.salon==='Линия'?'К кому хотите прийти?':'Ваш мастер — '+state.staff;return top+steps+`<p class="sub">${m}</p>`+(state.concept==='b'||state.salon!=='Линия'?'':`<div class="grid-two"><button class="choice ${state.staff==='Анна'?'sel':''}" data-action="staff" data-value="Анна"><strong>Анна</strong><small>Стилист · ★ 4,9</small></button><button class="choice ${state.staff==='Мария'?'sel':''}" data-action="staff" data-value="Мария"><strong>Мария</strong><small>Стилист · ★ 4,8</small></button></div>`)+`<h2>День</h2>${chips([['29 сен','29 сентября'],['30 сен','30 сентября'],['1 окт','1 октября']],state.date,'date')}<h2>${state.concept==='b'?'Варианты':'Свободное время'}</h2>${state.noSlots?note('Подходящих слотов пока нет','Измените день или оставьте условия для сообщения о новом окне.','warn'):`<div class="time-grid">${['12:00','15:00','16:30','18:00'].map(t=>`<button class="${state.slot===t?'sel':''}" data-action="slot" data-value="${t}">${t}${state.concept==='b'?`<br><small>${state.salon==='Линия'?(t==='16:30'?'Мария':'Анна'):state.staff}</small>`:''}</button>`).join('')}</div>${button('Продолжить','quote')}`}${act(state.noSlots?'Показать свободное время':'Показать состояние без слотов','toggleSlots','ghost')}${note('Ничего не подошло?','Оставьте удобные дни и время. Запрос не создаёт запись и не удерживает слот.')}${button('Сообщить об освободившемся времени','waitForm','secondary')}`}
function quote(){let discounted=state.benefit==='reward'?0:state.benefit==='coupon'?state.price-300:state.benefit==='promotion'?state.price-240:state.price;return heading('ПОЧТИ ГОТОВО','Проверьте запись','Подтвердите, только если всё подходит.')+`<div class="paper">${meta([['Салон','Линия'],['Услуга',h(state.service)],['Когда',h(state.date)+', '+h(state.slot)],['Мастер',h(state.staff)],['Длительность',state.duration+' минут']])}</div><h2>Выгода</h2>${chips([['Без выгоды','none'],['Награда','reward'],['Купон','coupon'],['Акция','promotion']],state.benefit,'benefit')}${state.benefit!=='none'?note('Применена одна выгода',state.benefit==='reward'?'Доступная награда на эту услугу.':state.benefit==='coupon'?'Купон партнёра −300 ₽.':'Временная акция −240 ₽.'):''}<div class="paper soft"><div class="row"><strong>Итого к оплате в салоне</strong><span class="big">${cash(discounted)}</span></div><p class="mini">В приложении оплаты нет. Время проверится ещё раз при подтверждении.</p></div>${button('Подтвердить запись','confirmed')}`}
function confirmed(){return heading('ГОТОВО','Вы записаны','Мы сохранили визит в ваших записях.')+`<div class="paper good"><span class="kicker">ЗАПИСЬ № ${state.booking.id}</span><div class="big">${h(state.booking.date)} · ${h(state.booking.time)}</div><p>${h(state.booking.service)} · ${h(state.booking.staff)}</p><strong>${cash(state.booking.price)}</strong></div>${button('Посмотреть запись','booking')}${button('На главную','home','secondary')}`}
function bookings(){return heading('ВАШЕ ВРЕМЯ','Мои записи','Ближайшие визиты и история во всех салонах.')+chips([['Ближайшие','bookings'],['История','history']],'bookings','screen')+(state.booking.cancelled?note('Пока нет ближайших визитов','После новой записи она появится здесь.'):card(`${h(state.booking.date)} · ${h(state.booking.time)}`,`${h(state.booking.service)} · ${h(state.booking.staff)} · ${h(state.booking.salon||'Линия')}`,'booking','ПОДТВЕРЖДЕНО'))+button('Записаться ещё',state.concept==='b'?'home':state.concept==='c'?'salon':'discover')}
function booking(){return heading('МОЯ ЗАПИСЬ',`${state.booking.date} · ${state.booking.time}`,'Подтверждена · № '+state.booking.id)+`<div class="paper">${meta([['Салон','Линия'],['Услуга',h(state.booking.service)],['Мастер',h(state.booking.staff)],['Стоимость',cash(state.booking.price)],['Адрес','ул. Лесная, 12']])}</div>${button('Хочу раньше','waitForm')}${button('Перенести на другое время','reschedule','secondary')}${button('Отменить запись','cancelPrompt','ghost')}${note('Что значит «Хочу раньше»?','Вы оставите пожелания и сохраните нынешнюю запись, пока не подтвердите новое время.')}`}
function reschedule(){return heading('ПЕРЕНОС','Выберите новое время','Запись № '+state.booking.id+' сохранится до подтверждения.')+slots()+note('Одна запись','После успешного переноса время изменится у существующей записи.')}
function history(){return heading('ИСТОРИЯ','Ваши прошлые визиты','Оцените мастера, если визит уже завершён.')+card('12 сентября · Линия','Стрижка и укладка · Анна · завершён','review')+card('20 августа · Точка','Маникюр · Елена · завершён','review')+card('3 июля · Линия','Укладка · Мария · завершён','review')}
function review(){return heading('ПОСЛЕ ВИЗИТА','Как вам работа Анны?','12 сентября · стрижка и укладка · Линия')+note('Оценка мастера','Поставьте от 1 до 5 звёзд. Текстовый отзыв не требуется.')+chips([['★','1'],['★★','2'],['★★★','3'],['★★★★','4'],['★★★★★','5']],state.stars||'5','stars')+button('Сохранить оценку','history')}
function waitlist(){return heading('ЖИВОЕ ОКНО','Ищем удобное время','Ваши активные и завершённые запросы.')+(state.request?card('Стрижка и укладка','29 сен — 5 окт · 09:00–18:00 · не запись','requestSaved','АКТИВЕН'):note('Запросов пока нет','Если при выборе времени ничего не подошло, оставьте предпочтения.'))+button('Создать запрос','waitForm')+note('Как это работает','Когда отмена освободит подходящее окно, предложим его одному клиенту. Слот остаётся общедоступным.')}
function waitForm(){return heading('ЖИВОЕ ОКНО',state.linked?'Можно прийти раньше':'Какое время подойдёт?',state.linked?`Текущая запись ${state.booking.date}, ${state.booking.time} останется, пока вы не примете предложение.`:`${state.service} · ${state.salon}. Запрос не является записью.`)+`<form id="waitForm"><div class="grid-two"><div><label for="from">С даты</label><input id="from" name="from" type="date" value="2026-09-29" required></div><div><label for="to">По дату</label><input id="to" name="to" type="date" value="${state.linked?'2026-10-02':'2026-10-05'}" required></div></div><label>Подходящие дни недели</label><div class="checks">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((v,i)=>`<label><input type="checkbox" name="day" value="${i+1}" ${i<5?'checked':''}>${v}</label>`).join('')}</div><div class="grid-two"><div><label for="start">Не раньше</label><input id="start" name="start" type="time" value="09:00" required></div><div><label for="end">Закончить до</label><input id="end" name="end" type="time" value="18:00" required></div></div><label>Подходящие мастера</label><div class="checks"><label><input type="checkbox" name="staff" value="Анна" checked>Анна</label><label><input type="checkbox" name="staff" value="Мария" checked>Мария</label></div><label for="notice">Минимум до визита · можно изменить</label><select id="notice" name="notice"><option value="60">1 час · по умолчанию</option><option value="120">2 часа</option><option value="360">6 часов</option><option value="1440">1 день</option></select>${note('Важное условие','Запрос не резервирует время. Если появится предложение, проверим слот снова при вашем принятии.')}<label class="checks" style="display:flex;align-items:center;gap:7px"><input type="checkbox" name="consent" required style="width:19px;min-height:19px">Согласен на сообщения только об этом запросе</label><button class="btn" type="submit">Создать запрос</button></form>`}
function requestSaved(){const p=state.prefs||{from:'2026-09-29',to:'2026-10-05',start:'09:00',end:'18:00',staff:['Анна','Мария'],notice:'60'};return heading('ЖИВОЕ ОКНО',state.request?'Ожидаем подходящее окно':'Запрос закрыт',state.request?'Это пока не запись. Ваше текущее время сохранено.':'Новых сообщений по этому запросу не будет.')+`<div class="paper"><strong>${h(state.service)}</strong>${sep}${meta([['Даты',niceDate(p.from)+' — '+niceDate(p.to)],['Время',h(p.start)+'–'+h(p.end)],['Мастера',p.staff.length?p.staff.map(h).join(', '):'Любой мастер'],['Минимум',p.notice==='60'?'1 час':p.notice==='120'?'2 часа':p.notice==='360'?'6 часов':'1 день']])}</div>${state.request?button('Изменить предпочтения','waitForm','secondary')+act('Приостановить запрос','pauseRequest','secondary')+act('Закрыть запрос','closeRequest','ghost')+`<div class="paper soft"><strong>В демо появилось окно</strong><p class="mini">Откройте пример предложения, чтобы проверить действия клиента.</p>${button('Посмотреть предложение','offer')}</div>`:button('К моим записям','bookings')}`}
function offer(){return heading('ЖИВОЕ ОКНО','Есть свободное время','Предложение действительно до 12:10 по Москве.')+`<div class="paper"><span class="kicker">${h(state.salon).toUpperCase()} · ДЛЯ ВАС</span><div class="big">29 сентября · 14:00</div><p>${h(state.service)} · ${h(state.staff)} · ${state.duration} минут</p><strong>Итого: ${cash(state.price)}</strong></div>${note('Время не зарезервировано','Оно доступно другим клиентам. При принятии проверим, свободен ли слот сейчас.','warn')}${state.linked?note('Перенесём существующую запись',`Запись № ${state.booking.id}: с ${state.booking.date}, ${state.booking.time} на 29 сентября, 14:00. Второй записи не будет.`):''}${act(state.linked?'Перенести мою запись':'Записаться','acceptOffer','primary')}${act('Не подходит · ждать дальше','declineOffer','secondary')}${act('Изменить запрос','editRequest','ghost')}${act('Больше не предлагать','closeRequest','ghost')}`}
function offerResult(){let lost=state.offerResult==='lost',declined=state.offerResult==='declined';return heading('ЖИВОЕ ОКНО',lost?'Это время уже занято':declined?'Будем искать дальше':state.linked?'Запись перенесена':'Вы записаны',lost?'Кто-то записался раньше. Ваш запрос продолжает ждать новое окно.':declined?'Это предложение закрыто. Запрос остаётся активным.':'Время подтверждено, результат сохранён в «Моих записях».')+note(state.linked?'Ваша исходная запись':'Состояние запроса',lost||declined?state.linked?`№ ${state.booking.id} на ${state.booking.date}, ${state.booking.time} остаётся без изменений.`:'Новая запись не создана.':'Предложение закрыто после успешного подтверждения.',lost?'warn':'good')+button('Мои записи','bookings')}
function loyalty(){return heading('МОИ НАГРАДЫ',state.concept==='c'?'Бонусы «Линии»':'Хорошо возвращаться','Награды и прогресс для каждой программы отдельно.')+`<div class="paper soft"><span class="kicker">ЛИНИЯ · СТРИЖКА И УКЛАДКА</span><div class="big">4 из 5</div><div class="progress"><i class="on"></i><i class="on"></i><i class="on"></i><i class="on"></i><i></i></div><p class="mini">Ещё один завершённый платный визит до следующей награды.</p></div>${card('Бесплатное посещение','1 из 2 осталось · срок до 31 декабря','quote','ДОСТУПНАЯ НАГРАДА')}${card('Скидка 10%','Другая программа на эту же услугу','quote')}${note('Одна выгода на запись','Награду, партнёрский купон и временную акцию вместе применить нельзя.')}${button('Посмотреть все предложения','offers','secondary')}`}
function offers(){return heading('ПРЕДЛОЖЕНИЯ','Для ваших планов','Проверяйте срок и условия перед выбором.')+card('−300 ₽ у партнёра','Купон салона «Точка» · до 30 ноября','promo','ПАРТНЁРСКИЙ КУПОН')+card('Осенняя укладка −10%','«Линия» · до 15 октября','promo','ВРЕМЕННАЯ АКЦИЯ')+note('Как применить','Выберите одно предложение при записи. Итог покажем до подтверждения.')}
function promo(){return heading('УСЛОВИЯ ПРЕДЛОЖЕНИЯ','Осенняя укладка','Временная акция салона «Линия».')+art('Ваш хороший день','До 15 октября')+meta([['Скидка','10%'],['Услуга','Укладка'],['Срок','До 15 октября'],['Оплата','В салоне']])+note('Условия','Акция действует при наличии свободных мест в лимите и не складывается с наградами и купонами.')+button('Выбрать время','slots')}
function events(){return heading('ЦЕНТР СОБЫТИЙ','Что нового','Только важное о визитах и ваших запросах.')+card('Предложение освободившегося времени','Сегодня, 12:00 · действительно до 12:10','offer','НОВОЕ')+card('Напоминание о записи','2 октября, 16:00 · Линия','booking')+card('Вам доступна награда','Линия · стрижка и укладка','loyalty')+button('Настроить сообщения','profile','secondary')}
function profile(){return heading('ВАШИ НАСТРОЙКИ','Профиль и сообщения','Сервисные сообщения и реклама настраиваются отдельно.')+`<div class="paper"><strong>Анна Смирнова</strong><p class="mini">Клиент MAX · ваши записи и награды</p></div>${state.concept==='c'?profileTheme():''}<h2>Сообщения</h2>${['Напоминания о визите','Сервисные предложения «Живого окна»','Рекламные предложения «Линии»'].map((t,i)=>`<div class="paper row"><div><strong>${t}</strong><div class="mini">${i===1?'Действуют только для активного запроса.':'Настройка для салона «Линия».'}</div></div><input type="checkbox" aria-label="${t}" ${i<2?'checked':''} style="width:22px;min-height:22px;accent-color:var(--accent)"></div>`).join('')}${note('Партнёрские условия','Согласие на конкретную версию партнёрской программы даётся отдельно.')}${button('Сменить кабинет','role','secondary')}`}
function profileTheme(){return `<section class="paper profile-theme" aria-label="Тема оформления"><strong>Тема оформления</strong><p class="mini">Выберите комфортный вид приложения</p><div class="profile-theme-options" role="group" aria-label="Цветовая тема"><button data-theme="light" class="${state.theme==='light'?'selected':''}" aria-pressed="${state.theme==='light'}"><span class="theme-swatch light" aria-hidden="true">☀</span><span>Светлая</span></button><button data-theme="dark" class="${state.theme==='dark'?'selected':''}" aria-pressed="${state.theme==='dark'}"><span class="theme-swatch dark" aria-hidden="true">☾</span><span>Тёмная</span></button></div></section>`}
function role(){return heading('ПРОСТРАНСТВО','Куда перейти?','Один человек может быть клиентом и сотрудником.')+`<div class="workspace-menu"><button data-action="role" data-value="client"><strong>Личный кабинет</strong><small>Мои записи, награды и предложения</small></button><button data-action="role" data-value="owner"><strong>Линия · владелец</strong><small>Салон, сотрудники, программы и отчёты</small></button><button data-action="role" data-value="admin"><strong>Линия · администратор</strong><small>День, календарь, клиенты и «Живое окно»</small></button><button data-action="role" data-value="master"><strong>Линия · мастер</strong><small>Только мои назначения и исход визита</small></button></div>${note('Роли разделены','Мастер не видит CRM, очередь предложений, стоимость или чужие назначения.')}`}
function workHome(){return heading('ЛИНИЯ · '+workRole(),'Сегодня в салоне','29 сентября · вторник · Москва')+`<div class="task-hero"><span class="kicker">СЕЙЧАС ВАЖНО</span><div class="big">Следующий визит в 12:00</div><p class="sub">Анна Смирнова · стрижка и укладка</p>${button('Открыть запись','workBooking')}</div>${card('Календарь записей','Месяц, мастера и расписание','calendar')}${card('Лояльность','Программы салона и совместные предложения','programs')}${card('Клиенты','Карточки, история и награды','customers')}${state.role==='owner'?card('Управление салоном','Услуги, график, сотрудники и оформление','catalog'):''}`}
function calendar(){if(state.concept==='c')return ownerCalendar();return heading('ЛИНИЯ · ДЕНЬ',state.concept==='a'?'План на сегодня':state.concept==='b'?'Сетка дня':'День в «Линии»','29 сентября · все мастера · Москва, UTC+3')+(state.concept==='b'?`<div class="filter-band">Дата: 29 сен　 ·　 Мастер: все　 ·　 День ▾</div>`:'')+chips([['Все','all'],['Анна','Анна'],['Мария','Мария']],'all','calStaff')+(state.concept==='b'?`<div class="timeline"><article><strong>09:00 · Ирина</strong><div class="mini">Анна · стрижка</div></article><article><strong>12:00 · Анна</strong><div class="mini">Анна · стрижка</div></article><article><strong>14:00 · Свободное окно</strong><div class="mini">Ждём ответ кандидата 02</div></article></div>`:card('09:00 · Ирина','Анна · стрижка · подтверждено','workBooking')+card('12:00 · Анна','Анна · стрижка · подтверждено','workBooking')+card('14:00 · окно',state.windowStopped?'Остановлено · время свободно':'Предложение отправлено одному клиенту','live'))+button('Записать клиента','newBooking')}
const recordWord=n=>n===1?'запись':n%10>1&&n%10<5&&(n%100<12||n%100>14)?'записи':'записей';
function ownerAppointments(day){const own=masterAppointments(day).map(([time,client,service,duration])=>({time,client,service,duration,staff:'Анна',status:'Подтверждена'}));const others={3:[['12:30','Марина','Окрашивание','Мария']],8:[['11:00','Ольга','Укладка','Мария'],['16:00','Вера','Маникюр','Елена']],12:[['15:00','Полина','Укладка','Мария']],18:[['09:30','Алина','Окрашивание','Мария'],['14:00','Вера','Маникюр','Елена']],24:[['10:00','Марина','Укладка','Мария']],29:[['10:30','Ольга','Укладка','Мария'],['16:00','Софья','Маникюр','Елена']]};let items=own.concat((others[day]||[]).map(([time,client,service,staff])=>({time,client,service,duration:'60 минут',staff,status:'Подтверждена'})));if(day===29&&state.ownerYear===2026&&state.ownerMonth===8)items.push({time:'14:00',client:'Свободное окно',service:'Стрижка и укладка',duration:'60 минут',staff:'Анна',status:'После отмены',live:true});return items.sort((a,b)=>a.time.localeCompare(b.time))}
function ownerVisibleAppointments(day){return ownerAppointments(day).filter(item=>state.ownerStaff==='all'||item.staff===state.ownerStaff)}
function ownerStaffOptions(){const items=[['all','Все мастера'],['Анна','Анна'],['Мария','Мария'],['Елена','Елена']].filter(([,name])=>name.toLocaleLowerCase('ru-RU').includes(state.ownerStaffQuery.trim().toLocaleLowerCase('ru-RU')));return items.length?items.map(([value,name])=>`<button role="option" aria-selected="${state.ownerStaff===value}" data-action="ownerStaff" data-value="${value}"><span>${name}</span>${state.ownerStaff===value?'<span aria-hidden="true">✓</span>':''}</button>`).join(''):'<p class="owner-staff-empty">Ничего не найдено</p>'}
function ownerAgendaRows(entries){const bookings=entries.map((item,index)=>({item,index})).filter(x=>!x.item.live),windows=entries.map((item,index)=>({item,index})).filter(x=>x.item.live),row=({item,index})=>`<button class="master-appointment paper ${item.live?'owner-live-entry':''}" data-go="workBooking" data-owner-index="${index}"><span class="master-time">${item.time}</span><span><strong>${item.client}</strong><small>${item.staff} · ${item.service}</small></span><span class="arrow">›</span></button>`;return (bookings.length?bookings.map(row).join(''):'<div class="paper master-no-appointments">На этот день записей нет</div>')+(windows.length?`<h3 class="owner-window-title">Освободившееся время</h3>${windows.map(row).join('')}`:'')}
function ownerCalendar(){const year=state.ownerYear,month=state.ownerMonth,days=new Date(year,month+1,0).getDate(),offset=(new Date(year,month,1).getDay()+6)%7,monthName=new Date(year,month,1).toLocaleDateString('ru-RU',{month:'long',year:'numeric'}),selected=state.ownerDate,selectedName=new Date(year,month,selected).toLocaleDateString('ru-RU',{day:'numeric',month:'long'}),entries=ownerVisibleAppointments(selected),count=entries.filter(x=>!x.live).length,total=Array.from({length:days},(_,i)=>ownerVisibleAppointments(i+1).filter(x=>!x.live).length).reduce((a,b)=>a+b,0),staffName=state.ownerStaff==='all'?'Все мастера':state.ownerStaff;return heading('ЛИНИЯ · КАЛЕНДАРЬ','Записи салона','Выберите мастера и день, чтобы посмотреть расписание.')+`<div class="owner-filter"><span class="filter-label">Мастер</span><button class="owner-staff-trigger" data-action="ownerStaffToggle" aria-expanded="${state.ownerStaffOpen}" aria-controls="owner-staff-list"><span>${staffName}</span><span aria-hidden="true">⌄</span></button>${state.ownerStaffOpen?`<div class="owner-staff-menu"><input type="search" data-owner-staff-search aria-label="Поиск мастера" placeholder="Найти мастера" value="${h(state.ownerStaffQuery)}"><div id="owner-staff-list" role="listbox" aria-label="Мастера" class="owner-staff-options">${ownerStaffOptions()}</div></div>`:''}</div><section class="master-calendar owner-calendar paper" aria-label="Календарь записей салона"><div class="master-month-head"><button data-action="ownerMonth" data-value="-1" aria-label="Предыдущий месяц">‹</button><div><strong>${monthName}</strong><span>${total} ${recordWord(total)} за месяц</span></div><button data-action="ownerMonth" data-value="1" aria-label="Следующий месяц">›</button></div><div class="master-days" aria-hidden="true">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</div><div class="master-grid">${Array.from({length:offset},()=>'<span class="master-empty"></span>').join('')}${Array.from({length:days},(_,i)=>{const day=i+1,n=ownerVisibleAppointments(day).filter(x=>!x.live).length;return `<button data-action="ownerDate" data-value="${day}" class="${day===selected?'selected':''}" aria-label="${new Date(year,month,day).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}, ${n} ${recordWord(n)}" aria-pressed="${day===selected}"><span>${day}</span>${n?`<small>${n}</small>`:''}</button>`}).join('')}</div></section><section class="master-agenda owner-agenda" aria-live="polite"><div class="master-agenda-title"><h2>${selectedName}</h2><span>${count} ${recordWord(count)}</span></div>${ownerAgendaRows(entries)}</section>`}
