function live(){return heading('ЛИНИЯ · ЖИВОЕ ОКНО','Свободные окна','Автоматическое предложение после отмены.')+`<div class="grid-two"><div class="paper"><strong class="big">3</strong><div class="mini">активных запроса</div></div><div class="paper"><strong class="big">1</strong><div class="mini">окно в работе</div></div></div><div class="paper"><span class="kicker">29 СЕНТЯБРЯ · 14:00 · АННА</span><h3>Стрижка и укладка</h3><p class="mini">${state.windowStopped?'Остановлено администратором':'Ответ до 12:10 · активен только кандидат 02'}</p></div><h2>Цепочка</h2><div class="timeline"><article>01 · отказался · 11:58</article><article>02 · ${state.windowStopped?'предложение отозвано':'ждём ответ'}</article><article>03 · ${state.windowStopped?'не отправлено':'следующий, ещё не уведомлён'}</article></div>${note('Очередь без ручного выбора','Один слот предлагается одному клиенту за раз. Сотрудник может остановить окно, но не переставить кандидатов.')}${state.windowStopped?'':act('Остановить это окно','toStop','secondary')}${state.concept==='c'?button('К карточке записи','workBooking','ghost'):''}`}
function masterAppointments(day){const entries={3:[['10:00','Ольга','Укладка','45 минут']],8:[['09:30','Ирина','Стрижка','60 минут'],['13:00','Анна','Стрижка и укладка','60 минут']],12:[['11:00','Софья','Укладка','45 минут']],18:[['10:00','Ольга','Стрижка','60 минут'],['12:30','Ирина','Укладка','45 минут'],['16:00','Анна','Стрижка и укладка','60 минут']],24:[['14:00','Софья','Стрижка','60 минут']],29:[['09:00','Ирина','Стрижка','60 минут'],['12:00','Анна','Стрижка и укладка','60 минут']]};return (entries[day]||[]).slice().sort((a,b)=>a[0].localeCompare(b[0]))}
function masterDay(){const year=state.masterYear,month=state.masterMonth,days=new Date(year,month+1,0).getDate(),offset=(new Date(year,month,1).getDay()+6)%7,monthName=new Date(year,month,1).toLocaleDateString('ru-RU',{month:'long',year:'numeric'}),selected=state.masterDate,selectedName=new Date(year,month,selected).toLocaleDateString('ru-RU',{day:'numeric',month:'long'}),appointments=masterAppointments(selected),total=Array.from({length:days},(_,i)=>masterAppointments(i+1).length).reduce((a,b)=>a+b,0);return heading('ЛИНИЯ · МАСТЕР','Мои записи','Выберите день, чтобы посмотреть свои записи по времени.')+`<section class="master-calendar paper" aria-label="Календарь записей мастера"><div class="master-month-head"><button data-action="masterMonth" data-value="-1" aria-label="Предыдущий месяц">‹</button><div><strong>${monthName}</strong><span>${total} записей за месяц</span></div><button data-action="masterMonth" data-value="1" aria-label="Следующий месяц">›</button></div><div class="master-days" aria-hidden="true">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</div><div class="master-grid">${Array.from({length:offset},()=>'<span class="master-empty"></span>').join('')}${Array.from({length:days},(_,i)=>{const day=i+1,count=masterAppointments(day).length;return `<button data-action="masterDate" data-value="${day}" class="${day===selected?'selected':''}" aria-label="${new Date(year,month,day).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}, ${count} ${count===1?'запись':count>1&&count<5?'записи':'записей'}" aria-pressed="${day===selected}"><span>${day}</span>${count?`<small>${count}</small>`:''}</button>`}).join('')}</div></section><section class="master-agenda" aria-live="polite"><div class="master-agenda-title"><h2>${selectedName}</h2><span>${appointments.length} ${appointments.length===1?'запись':appointments.length>1&&appointments.length<5?'записи':'записей'}</span></div>${appointments.length?appointments.map(([time,name,service,duration],index)=>`<button class="master-appointment paper" data-go="masterVisit" data-master-index="${index}"><span class="master-time">${time}</span><span><strong>${name}</strong><small>${service} · ${duration}</small></span><span class="arrow">›</span></button>`).join(''):`<div class="paper master-no-appointments">На этот день записей нет</div>`}</section>`}
function masterVisit(){const [time,name,service,duration]=state.masterAppointment||masterAppointments(state.masterDate)[0]||['12:00','Анна','Стрижка и укладка','60 минут'];return heading('МОЁ НАЗНАЧЕНИЕ',`${time} · ${name}`,`${service} · ${duration}`)+(state.visitResult?note(state.visitResult,'Изменение сохранено в демонстрации.','good')+button('Вернуться к календарю','masterDay'):note('Визит ещё не начался','Отметка результата станет доступна после начала. Для демо покажем состояние завершения.')+act('Отметить завершение','visitDone','primary')+act('Отметить неявку','visitNoShow','secondary'))}
function catalog(){return heading('ЛИНИЯ · УПРАВЛЕНИЕ','Услуги и мастера','Цена, длительность и доступные исполнители.')+card('Стрижка и укладка','60 минут · 2 400 ₽ · Анна, Мария','service')+card('Укладка','45 минут · 1 600 ₽ · Мария','service')+button('Добавить услугу','service')+button('График мастеров','schedule','secondary')}
