function analytics(){return heading('ЛИНИЯ · СТАТИСТИКА','Как прошёл месяц','29 сентября · данные по этому салону.')+`<div class="grid-two"><div class="paper"><span class="big">84</span><div class="mini">завершённых визита</div></div><div class="paper"><span class="big">72%</span><div class="mini">загрузка времени</div></div></div>${card('Услуги','Стрижка и укладка · 39 визитов','catalog')}${card('Возвращаются','32 клиента пришли снова','customers')}${note('Стоимость услуг','Показатель справочный и не равен кассовой выручке: приложение не принимает оплату.')}`}
