function workPromos(){return heading('ЛИНИЯ · АКЦИИ','Временные акции','Свои акции и предложения партнёрам.')+card('Осенняя укладка −10%','Активна до 15 октября · 8 из 20 применений','workPromos')+card('Маникюр у партнёра −300 ₽','Ждём подтверждения салона «Точка»','workPromos')+note('Публикация и лимит','Собственная акция доступна сразу; партнёрская — после подтверждения. Место в лимите резервируется при записи.')+button('Создать акцию','workPromos')}
function settings(){return heading('ЛИНИЯ · НАСТРОЙКИ','Как видят ваш салон','Профиль, оформление и публикация.')+card('Витрина','Описание, логотип, обложка и категории','salon')+card('Состояние салона','Опубликован · доступен клиентам','settings')+card('Ссылка и QR','Открыть салон внутри MAX','settings')+note('Перед публикацией','Проверьте услугу, мастера и расписание.')}
