function benefitPicker(){return chips([['Без выгоды','none'],['Награда','reward'],['Купон','coupon'],['Акция','promotion']],state.benefit,'benefit')}
function quotePrice(){return state.benefit==='reward'?0:state.benefit==='coupon'?Math.max(0,state.price-300):state.benefit==='promotion'?Math.max(0,state.price-240):state.price}
function renderQuote(){const c=state.concept;
 if(c==='a')return heading('ШАГ 3 ИЗ 3','Всё подходит?','Пройдёмся по выбору перед подтверждением.')+`<div class="step-head"><i class="on"></i><i class="on"></i><i class="on"></i></div>${card('1 · Ваше место',h(state.salon)+' · ул. Лесная, 12','salon')}${card('2 · Визит',`${h(state.service)} · ${h(state.staff)} · ${h(state.date)}, ${h(state.slot)}`,'slots')}<h2>Можно применить одну выгоду</h2>${benefitPicker()}<div class="paper soft"><div class="row"><strong>Итого в салоне</strong><span class="big">${cash(quotePrice())}</span></div><p class="mini">Приложение не принимает оплату. Доступность проверим при подтверждении.</p></div>${button(state.rescheduling?'Подтвердить перенос':'Да, записаться','confirmed')}`;
 if(c==='b')return heading('РЕЗУЛЬТАТ ПОИСКА','Выбранное время','Всё о варианте на одном экране.')+`<div class="paper"><span class="kicker">${h(state.date)} · ${h(state.slot)}</span><div class="big">${h(state.slot)}</div><h3>${h(state.service)} · ${h(state.staff)}</h3><p class="mini">${h(state.salon)} · ${state.duration} минут · Москва, UTC+3</p></div><div class="filter-band"><strong>Другие варианты рядом</strong><div class="chips"><button data-action="slot" data-value="16:30">16:30 · Мария</button><button data-action="slot" data-value="18:00">18:00 · Анна</button></div></div><h2>Условия и цена</h2>${benefitPicker()}<div class="paper soft">${meta([['Стоимость услуги',cash(state.price)],['Одна выгода',state.benefit==='none'?'Не выбрана':state.benefit==='reward'?'Награда':state.benefit==='coupon'?'Купон':'Акция'],['Итого',cash(quotePrice())]])}<p class="mini">Время проверится снова при подтверждении. Оплата в салоне.</p></div>${button(state.rescheduling?'Перенести запись':'Подтвердить вариант','confirmed')}`;
 return heading(`МОЁ МЕСТО / ${h(state.salon).toUpperCase()}`,`Визит в «${inSalon()}»`,'Соберём ваш визит и выгоду в одном месте.')+art('До скорой встречи','Знакомый салон, знакомые люди')+`<div class="paper">${meta([['Услуга',h(state.service)],['Ваш мастер',h(state.staff)],['Дата и время',h(state.date)+', '+h(state.slot)],['Длительность',state.duration+' минут']])}</div><h2>Ваши бонусы здесь</h2>${benefitPicker()}<div class="paper soft"><span class="kicker">ИТОГО К ОПЛАТЕ В «${inSalon().toUpperCase()}»</span><div class="big">${cash(quotePrice())}</div><p class="mini">Запись появится в «Моих визитах». Оплата после визита.</p></div>${button(state.rescheduling?'Сохранить новое время':'Подтвердить визит','confirmed')}`}
function renderBooking(){const b=state.booking,c=state.concept,summary=`${h(b.service)} · ${h(b.staff)} · ${cash(b.price)}`;
 if(c==='a')return heading('ВАШ СЛЕДУЮЩИЙ ВИЗИТ',`${h(b.date)} · ${h(b.time)}`,'Подтверждена · запись № '+b.id)+`<div class="paper soft"><strong>${summary}</strong><p class="mini">${h(b.salon||'Линия')} · Москва</p></div><h2>Что хотите сделать?</h2>${button('Хочу прийти раньше','waitForm')}${button('Выбрать другое время','reschedule','secondary')}${button('Отменить запись','cancel','ghost')}${note('Пока вы ждёте время раньше','Эта запись остаётся у вас. Перенесём её только после вашего подтверждения.')}`;
 if(c==='b')return heading('МОИ ВИЗИТЫ','Ваше время в календаре','Запись № '+b.id+' · подтверждена')+`<div class="timeline"><article><strong>${h(b.date)}, ${h(b.time)}</strong><div class="mini">${summary}</div></article><article><strong>Приходите за 5 минут</strong><div class="mini">Линия · ул. Лесная, 12</div></article></div><div class="paper"><strong>Изменить время</strong><p class="mini">Посмотрите свободные слоты или оставьте запрос на более раннее окно.</p>${button('Смотреть свободные слоты','reschedule')}${button('Хочу раньше','waitForm','secondary')}</div>${button('Отменить запись','cancel','ghost')}`;
 let place=hybridSalons.find(x=>x.name===b.salon)||hybridSalons[0];return `<div class="salon-header">МОЁ МЕСТО / ${h(place.name).toUpperCase()}</div>${art('Скоро увидимся',`${h(place.kind)} · ${h(place.address)}`)}${heading('МОЙ ВИЗИТ',`${h(b.date)} · ${h(b.time)}`,'Подтверждена · № '+b.id)}<div class="paper">${meta([['Услуга',h(b.service)],['Мастер',h(b.staff)],['Оплата в салоне',cash(b.price)]])}</div>${button('Найти время раньше','waitForm')}${button('Обычный перенос','reschedule','secondary')}${button('Отменить запись','cancel','ghost')}${button('Назад в «'+h(place.name)+'»','salon','secondary')}`}
function renderReschedule(){return heading('ПЕРЕНОС ЗАПИСИ','Новое время','Запись № '+state.booking.id+' останется, пока вы не подтвердите перенос.')+chips([['29 сен','29 сентября'],['30 сен','30 сентября'],['1 окт','1 октября']],state.date,'date')+`<h2>Свободно у ${h(state.staff)}</h2><div class="time-grid">${['12:00','15:00','16:30'].map(t=>`<button class="${state.slot===t?'sel':''}" data-action="slot" data-value="${t}">${t}</button>`).join('')}</div>${note('После подтверждения','Изменим время записи № '+state.booking.id+'. Вторая запись не появится.')} ${button('Проверить новое время','quote')}`}
function cancel(){return heading('ВАЖНОЕ ДЕЙСТВИЕ','Отменить запись?','Запись № '+state.booking.id+' · '+state.booking.date+', '+state.booking.time)+note('После отмены','Ваше время освободится. Если была зарезервирована награда, она вернётся при действующем сроке.','warn')+act('Да, отменить запись','confirmCancel','danger')+button('Сохранить запись','booking','secondary')}
function cancelled(){return heading('МОИ ЗАПИСИ','Запись отменена','Запись № '+state.booking.id+' больше не занимает время.')+note('Всё в порядке','Если была применена действующая награда, она снова доступна по правилам программы.','good')+button('Выбрать другое время','slots')+button('К моим записям','bookings','secondary')}
function stop(){return heading('ЛИНИЯ · ЖИВОЕ ОКНО','Остановить это окно?','29 сентября · 14:00 · Анна')+note('Что произойдёт','Активное предложение будет отозвано. Следующему кандидату сообщение не отправим. Запросы сохранятся для других окон.','warn')+`<label for="stopReason">Причина остановки</label><input id="stopReason" value="Решение администратора">${act('Да, остановить окно','confirmStop','danger')}${button('Оставить окно активным','live','secondary')}`}
function renderWorkHome(){let c=state.concept;
 if(c==='a')return workHome();
 if(c==='b')return heading('ЛИНИЯ / СЕГОДНЯ','День по часам','Видно занятое время и ближайшие свободные интервалы.')+`<div class="filter-band">29 сентября　▾　　 Все мастера　▾</div><div class="timeline"><article><strong>09:00–10:00 · Ирина</strong><div class="mini">Анна · стрижка · подтверждена</div></article><article><strong>12:00–13:00 · Анна</strong><div class="mini">Анна · стрижка · подтверждена</div></article><article><strong>14:00–15:00 · свободное окно</strong><div class="mini">Предложение у кандидата 02 до 12:10</div></article></div>${button('Открыть календарь','calendar')}${button('Записать клиента','newBooking','secondary')}`;
 return heading('ЛИНИЯ / УПРАВЛЕНИЕ','Сегодня в «Линии»','Короткая сводка места и доступ к рабочим задачам.')+art('Ваш салон работает','4 визита сегодня')+`<div class="grid-two"><div class="paper"><span class="big">4</span><div class="mini">визита сегодня</div></div><div class="paper"><span class="big">1</span><div class="mini">окно после отмены</div></div></div>${card('Календарь салона','Месяц, мастера и записи','calendar')}${card('Клиенты «Линии»','Визиты, заметки, награды','customers')}${card('Лояльность','Свои программы и совместные предложения','programs')}${card('Оформление места','Витрина, адрес и график','settings')}`}
function renderCustomers(){if(state.concept==='a')return customers();if(state.concept==='b')return heading('ЛИНИЯ / КЛИЕНТЫ','Найти клиента','Быстрый рабочий список со следующими визитами.')+`<div class="search-input"><span>⌕</span><input placeholder="Имя или контакт"></div><div class="paper"><div class="row"><span class="kicker">КЛИЕНТ</span><span class="kicker">СЛЕДУЮЩИЙ</span></div>${[['Анна Смирнова','Сегодня · 12:00'],['Ирина Волкова','Сегодня · 09:00'],['Ольга Орлова','Завтра · 13:00']].map(([a,b])=>`<button class="touch" data-go="customer"><div class="touch-row"><strong>${a}</strong><span>${b}　›</span></div></button>`).join('')}</div>${button('Добавить клиента','customer','secondary')}`;return heading('ЛИНИЯ / ЛЮДИ','Клиенты «Линии»','Постоянные отношения видны вместе с визитами и наградами.')+card('Анна Смирнова','8 визитов · 1 доступная награда','customer','ЧАСТЫЙ ГОСТЬ')+card('Ирина Волкова','Первый визит сегодня','customer','НОВЫЙ ГОСТЬ')+card('Ольга Орлова','2 визита · знакомый мастер','customer')+note('Только для своей команды','Внутренние заметки не видят клиенты или салоны партнёров.')}
function contents(){switch(state.screen){case'home':return home();case'discover':return discover();case'salon':return salon();case'service':return service();case'slots':return slots();case'quote':return renderQuote();case'confirmed':return confirmed();case'bookings':return bookings();case'booking':return renderBooking();case'reschedule':return renderReschedule();case'cancel':return cancel();case'cancelled':return cancelled();case'history':return history();case'review':return review();case'waitlist':return waitlist();case'waitForm':return waitForm();case'requestSaved':return requestSaved();case'offer':return offer();case'offerResult':return offerResult();case'loyalty':return state.concept==='c'?cLoyalty():loyalty();case'offers':return offers();case'promo':return promo();case'events':return events();case'profile':return profile();case'role':return role();case'workHome':return renderWorkHome();case'calendar':return calendar();case'workBooking':return workBooking();case'newBooking':return newBooking();case'customers':return renderCustomers();case'customer':return customer();case'live':return live();case'stop':return stop();case'masterDay':return masterDay();case'masterVisit':return masterVisit();case'catalog':return catalog();case'schedule':return schedule();case'analytics':return analytics();case'programs':return programs();case'partners':return partners();case'workPromos':return workPromos();case'settings':return settings();case'access':return access();case'audit':return audit();case'createSalon':return createSalon();case'invite':return invite();default:return home()}}
function bottom(){let c=state.concept;if(c==='c'&&state.role==='client')return cBottom();let links=state.role==='client'?(c==='a'?[['◡','Главная','home'],['⌕','Найти','discover'],['▣','Записи','bookings'],['••','Ещё','profile']]:c==='b'?[['⌕','Поиск','home'],['◷','Визиты','bookings'],['✧','Выгоды','offers'],['○','Профиль','profile']]:c==='bc'?[['⌕','Поиск','home'],['⌂','Места','discover'],['▣','Записи','bookings'],['✧','Бонусы','loyalty']]:[['⌂','Мои места','home'],['⌕','Поиск','discover'],['▣','Записи','bookings'],['✧','Бонусы','loyalty']]):state.role==='master'?[['▦','Месяц','masterDay'],['○','Кабинет','role']]:c==='b'?[['▦','Календарь','calendar'],['⌕','Клиенты','customers'],['✧','Лояльность','programs'],['••','Ещё','workHome']]:[['⌂','Сегодня','workHome'],['▦','Календарь','calendar'],['✧','Лояльность','programs'],['••','Ещё','role']];return `<nav class="bottom" aria-label="Основная навигация">${links.map(([ico,label,to])=>`<button data-go="${to}" class="${state.screen===to?'active':''}"><span class="ico">${ico}</span>${label}</button>`).join('')}</nav>`}
function phone(){return `<div class="app-screen ${state.concept}"><div class="status"><span>9:41</span><span>●●●　▰</span></div><header class="app-top"><button class="back" data-action="back" aria-label="Назад">‹</button><div class="brand">ря<span>дом</span></div><div class="top-actions"><button data-go="role">${state.role==='client'?'Личный':state.role==='master'?'Мастер':'Линия'} ▾</button></div></header><div class="scroll">${contents()}</div>${bottom()}</div>`}
function wide(){let s=state.screen;return `<div class="app-screen ${state.concept} desktop"><aside><strong>рядом <span class="mini">/ Линия</span></strong>${[['workHome','Сегодня'],['calendar','Календарь'],['customers','Клиенты'],['programs','Лояльность'],['catalog','Услуги'],['analytics','Статистика']].map(([id,label])=>`<button data-go="${id}" class="${s===id?'sel':''}">${label}</button>`).join('')}</aside><main><div class="workhero"><div><span class="kicker">ЛИНИЯ · ${workRole()}</span><h2>${s==='customers'?'Клиенты салона':s==='live'?'Живое окно':'Вторник, 29 сентября'}</h2><p>Москва, UTC+3 · ${s==='calendar'?'все мастера':s==='customers'?'свои клиенты':'операционные задачи'}</p></div><button class="btn" data-go="newBooking">Записать клиента</button></div>${s==='customers'?`<div class="table"><div class="table-row head"><span>КЛИЕНТ</span><span>ТЕГ</span><span>БЛИЖАЙШИЙ ВИЗИТ</span><span>ПРОГРЕСС</span></div>${[['Анна Смирнова','Постоянный','29 сен · 12:00','4/5'],['Ирина Волкова','Новый','29 сен · 09:00','0/5'],['Ольга Орлова','Постоянный','30 сен · 13:00','2/5']].map(r=>`<div class="table-row">${r.map(x=>`<span>${x}</span>`).join('')}</div>`).join('')}</div><div class="board"><div class="paper"><h3>Анна Смирнова</h3><p>8 визитов в «Линию»</p><span class="mini">Внутренняя заметка: любит утро</span></div><div class="paper"><h3>Награды</h3><p>4/5 в новом цикле</p><span class="mini">1 награда доступна</span></div><div class="paper"><h3>Следующий визит</h3><p>29 сентября, 12:00</p><span class="mini">Анна · стрижка</span></div></div>`:s==='live'?`<div class="board"><div class="paper"><span class="big">3</span><p>активных запроса</p></div><div class="paper"><span class="big">1</span><p>окно в работе</p></div><div class="paper"><span class="big">12:10</span><p>ответ кандидата 02</p></div></div><div class="paper" style="margin-top:22px"><h3>29 сентября · 14:00 · Анна</h3><p>01 отказался → 02 ждём ответ → 03 ещё не уведомлён</p></div>`:`<div class="wide-timeline"><div>ВРЕМЯ</div><div>АННА</div><div>МАРИЯ</div><div>ЕЛЕНА</div>${['09:00','10:00','11:00','12:00','13:00','14:00','15:00'].map((t,i)=>`<div>${t}</div><div>${i===0?'<div class="block">Ирина · стрижка</div>':i===3?'<div class="block">Анна · стрижка</div>':i===5?'<div class="block">Свободное окно<br>Ждём ответ 02</div>':''}</div><div>${i===1?'<div class="block">Ольга · укладка</div>':''}</div><div>${i===4?'<div class="block">Софья · стрижка</div>':''}</div>`).join('')}</div>`}</main></div>`}
function side(){let c=concepts[state.concept];let routes=state.role==='client'?(state.concept==='a'?[['Новая запись','discover'],['Хочу раньше','booking'],['Награда','loyalty']]:state.concept==='b'?[['Найти время','home'],['Сравнить варианты','discover'],['Запросить окно','waitForm']]:state.concept==='bc'?[['Изменить фильтры','home'],['Карточки салонов','discover'],['Моё место','salon']]:[['Моё место','salon'],['Визиты салона','booking'],['Мои бонусы','loyalty']]):[['День салона',workRoot()],['Календарь','calendar'],['Лояльность','programs']];return `<aside class="explain"><div class="eyebrow">НАПРАВЛЕНИЕ ${state.concept.toUpperCase()} / ${state.role==='client'?'КЛИЕНТ':'САЛОН'}</div><h3>${c.name}</h3><p>${c.logic}</p><div class="why"><h4>Что меняется в опыте</h4><ul>${c.benefits.map(x=>`<li>${x}</li>`).join('')}</ul><p><strong>Компромисс:</strong> ${c.trade}</p></div><div class="why journey"><h4>Быстрые маршруты</h4>${routes.map(([label,to])=>`<button data-go="${to}">${label} →</button>`).join('')}</div><p class="bottom-note">Это демонстрация взаимодействия. Данные вымышлены; сообщения и записи на сервере не создаются.</p></aside>`}
function sidebar(){return `<nav class="lab-nav" aria-label="Все экраны приложения"><button class="${state.screen==='home'?'active':''}" data-go="home">Обзор концепции<small>как начинается путь</small></button>${Object.entries(groups).map(([group,items])=>`<h2>${group}</h2>${items.map(([id,title])=>`<button class="${state.screen===id?'active':''}" data-go="${id}">${title}</button>`).join('')}`).join('')}</nav>`}
function compare(){return `<section class="compare"><h2>Три идеи и объединение B+C</h2><div class="compare-grid">${Object.entries(concepts).map(([id,c])=>`<article><span class="kicker">${id==='bc'?'ВЫБРАННОЕ СОЧЕТАНИЕ':'НАПРАВЛЕНИЕ '+id.toUpperCase()}</span><h3>${c.name}</h3><p>${c.thesis}</p><strong>${id==='a'?'Задача → подсказка → итог':id==='b'?'Время → сравнение → выбор':id==='c'?'Салон → отношения → действие':'Фильтры → карточки салонов → запись'}</strong></article>`).join('')}</div><div class="comparison-table"><div class="comparison-row head"><span>КРИТЕРИЙ</span><span>A · ШАГИ</span><span>B · ВРЕМЯ</span><span>C · МЕСТА</span><span>B+C · ОБЪЕДИНЕНИЕ</span></div><div class="comparison-row"><span>Первый шаг</span><span>Следующее действие</span><span>Поиск времени</span><span>Выбор салона</span><span>Услуга, день и время</span></div><div class="comparison-row"><span>Представление вариантов</span><span>По одному шагу</span><span>Плотный список</span><span>Карточки салонов</span><span>Карточки с доступным временем</span></div><div class="comparison-row"><span>Польза постоянному клиенту</span><span>Подсказка</span><span>Быстрый поиск</span><span>История и награды</span><span>Быстрый поиск в своих местах</span></div><div class="comparison-row"><span>Мобильный mini-app</span><span>Спокойный путь</span><span>Плотные фильтры</span><span>Короткий путь к месту</span><span>Фильтры сворачиваются в верхний блок</span></div></div><p class="bottom-note">В каждом направлении доступны те же ${Object.keys(screens).length} экранов. B+C сохраняет параметры поиска сверху и показывает результаты карточками салонов.</p></section>`}
function render(){if(state.concept==='c')return renderC();let c=concepts[state.concept];app.innerHTML=`<div class="page"><div class="lab"><header class="lab-head"><div><span class="label">РЯДОМ / ПЕРЕСМОТР ОПЫТА</span><h1>Время в хороших местах</h1><p>Новый вариант B+C соединяет верхние фильтры поиска с карточками салонов. Сравните его с исходными направлениями на телефоне и компьютере.</p></div><a class="link" href="about.html">Охват и правила ↗</a></header>${sidebar()}<main class="stage"><div class="concepts">${Object.entries(concepts).map(([id,x])=>`<button data-concept="${id}" class="${state.concept===id?'active '+id:''}"><strong>${id.toUpperCase()} · ${x.name}</strong><small>${x.short}</small></button>`).join('')}</div><div class="stage-top"><div><h2>${screens[state.screen]||'Обзор'}</h2><p>${c.thesis}</p></div><div class="stage-controls"><div class="view-mode" aria-label="Размер экрана"><button data-view="phone" class="${state.view==='phone'?'active':''}">Телефон</button><button data-view="desktop" class="${state.view==='desktop'?'active':''}">Компьютер</button></div><div class="mode"><button data-role="client" class="${state.role==='client'?'active':''}">Клиент</button><button data-role="owner" class="${state.role==='owner'?'active':''}">Владелец</button><button data-role="admin" class="${state.role==='admin'?'active':''}">Администратор</button><button data-role="master" class="${state.role==='master'?'active':''}">Мастер</button></div></div></div>${state.view==='phone'?`<div class="stage-body"><div class="device-wrap"><p class="device-label">MAX MINI-APP · 390 × 844</p><div class="device">${phone()}</div></div>${side()}</div>`:desktopPreview()}${compare()}</main></div></div>`;app.querySelector('.device .scroll')?.scrollTo(0,0)}
app.addEventListener('click',e=>{let el=e.target.closest('[data-go],[data-concept],[data-role],[data-view],[data-action]');if(!el)return;if(el.dataset.concept){state.concept=el.dataset.concept;render();return}if(el.dataset.view){state.view=el.dataset.view;render();return}if(el.dataset.role){state.role=el.dataset.role;state.screen=state.role==='client'?'home':workRoot();state.history=[];render();return}if(el.dataset.go){if(el.dataset.go==='masterVisit'&&el.dataset.masterIndex!==undefined){state.masterAppointment=masterAppointments(state.masterDate)[Number(el.dataset.masterIndex)];state.visitResult=null}if(el.dataset.go==='workBooking'&&el.dataset.ownerIndex!==undefined)state.ownerAppointment=ownerVisibleAppointments(state.ownerDate)[Number(el.dataset.ownerIndex)];go(el.dataset.go);return}let a=el.dataset.action,v=el.dataset.value;if(a==='back'){state.screen=state.history.pop()||'home';render()}else if(a==='role'){state.role=v;state.screen=v==='client'?'home':workRoot();state.history=[];render()}else if(a==='section'){state.section=v;render()}else if(a==='screen'){go(v)}else if(a==='toHome'){go('home')}else if(a==='staff'){state.staff=v;render()}else if(a==='slot'){state.slot=v;render()}else if(a==='date'){state.date=v;render()}else if(a==='masterMonth'){let d=new Date(state.masterYear,state.masterMonth+Number(v),1);state.masterYear=d.getFullYear();state.masterMonth=d.getMonth();state.masterDate=3;render()}else if(a==='masterDate'){state.masterDate=Number(v);render()}else if(a==='ownerMonth'){let d=new Date(state.ownerYear,state.ownerMonth+Number(v),1);state.ownerYear=d.getFullYear();state.ownerMonth=d.getMonth();state.ownerDate=3;state.ownerAppointment=null;render()}else if(a==='ownerDate'){state.ownerDate=Number(v);state.ownerAppointment=null;render()}else if(a==='ownerStaffToggle'){state.ownerStaffOpen=!state.ownerStaffOpen;state.ownerStaffQuery='';render();if(state.ownerStaffOpen)app.querySelector('[data-owner-staff-search]')?.focus()}else if(a==='ownerStaff'){state.ownerStaff=v;state.ownerStaffOpen=false;state.ownerStaffQuery='';state.ownerAppointment=null;render()}else if(a==='benefit'){state.benefit=v;render()}else if(a==='stars'){state.stars=v;render()}else if(a==='inviteRole'){state.inviteRole=v;render()}else if(a==='acceptOffer'){state.offerResult='success';state.request=false;if(state.linked){state.booking={...state.booking,date:'29 сентября',time:'14:00'};}else{state.booking={id:String(Number(state.booking.id)+1),date:'29 сентября',time:'14:00',service:state.service,staff:state.staff,price:state.price,salon:state.salon,cancelled:false}}go('offerResult')}else if(a==='declineOffer'){state.offerResult='declined';go('offerResult')}else if(a==='editRequest'){go('waitForm')}else if(a==='closeRequest'){state.request=false;go('requestSaved')}else if(a==='pauseRequest'){state.request=false;go('requestSaved')}else if(a==='stopWindow'){state.windowStopped=true;render()}else if(a==='visitDone'||a==='visitNoShow'){state.visitResult=a==='visitDone'?'Визит завершён':'Неявка отмечена';render()} });
app.addEventListener('submit',e=>{if(e.target.id!=='waitForm')return;e.preventDefault();let f=new FormData(e.target);let days=f.getAll('day'),from=f.get('from'),to=f.get('to'),start=f.get('start'),end=f.get('end');if(!days.length||to<from||end<=start){alert('Проверьте даты, дни и время.');return}state.request=true;state.prefs={from,to,start,end,days,staff:f.getAll('staff'),notice:f.get('notice')};go('requestSaved')});
app.addEventListener('click',e=>{const el=e.target.closest('[data-go]');if(!el)return;const target=el.dataset.go,label=el.textContent;if(target==='salon'){if(label.includes('Точка'))state.salon='Точка';else if(label.includes('Клевер'))state.salon='Клевер';else if(label.includes('Линия')||label.includes('моё место'))state.salon='Линия'}if(target==='service'){if(label.includes('Маникюр')||state.salon==='Точка'){state.service='Маникюр';state.duration=60;state.price=1800;state.staff='Елена'}else if(label.includes('Массаж')||state.salon==='Клевер'){state.service='Массаж';state.duration=60;state.price=2800;state.staff='Ольга'}else if(label.includes('Укладка')&&!label.includes('Стрижка')){state.service='Укладка';state.duration=45;state.price=1600;state.staff='Мария'}else{state.service='Стрижка и укладка';state.duration=60;state.price=2400;state.staff='Анна'}}if(target==='quote'&&(label.toLowerCase().includes('маникюр')||label.includes('Точка')||label.includes('Елена'))){state.salon='Точка';state.service='Маникюр';state.duration=60;state.price=1800;state.staff='Елена'}if(target==='quote'&&label.includes('Линия')){state.salon='Линия';state.service='Стрижка и укладка';state.duration=60;state.price=2400;state.staff='Анна'}if(target==='quote'&&label.includes('15:00'))state.slot='15:00';if(target==='quote'&&label.includes('17:00'))state.slot='17:00';if(target==='quote'&&label.includes('16:30')){state.slot='16:30';if(state.salon==='Линия')state.staff='Мария'}},true);
function go(to){if(!to||!screens[to])return;const from=state.screen;if(to==='workHome')state.ownerAppointment=null;if(to==='home'&&state.concept==='c')state.salon='Линия';if(from!==to)state.history.push(from);if(['home','discover','salon','service'].includes(to))state.rescheduling=false;if(to==='reschedule')state.rescheduling=true;if(to==='slots'&&!state.rescheduling){state.benefit='none';state.noSlots=false}if(to==='waitForm'){if(from==='booking')state.linked=true;if(['slots','discover','service'].includes(from))state.linked=false}if(to==='confirmed'){let price=quotePrice();if(state.rescheduling){state.booking={...state.booking,date:state.date,time:state.slot,staff:state.staff,price};state.rescheduling=false}else state.booking={id:String(Number(state.booking.id)+1),date:state.date,time:state.slot,service:state.service,staff:state.staff,price,salon:state.salon,cancelled:false}}if(client.has(to)&&state.role!=='client')state.role='client';else if(master.has(to)&&to!=='role')state.role='master';else if(!client.has(to)&&!master.has(to)&&to!=='role'&&to!=='invite'&&state.role==='client')state.role='owner';else if(!client.has(to)&&!master.has(to)&&to!=='role'&&state.role==='master')state.role='admin';if(['programs','partners','workPromos','settings','access','createSalon'].includes(to))state.role='owner';state.screen=to;render()}
app.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='toggleSlots'){e.stopImmediatePropagation();state.noSlots=!state.noSlots;render()}else if(a==='toStop'){e.stopImmediatePropagation();go('stop')}else if(a==='confirmStop'){e.stopImmediatePropagation();let reason=app.querySelector('#stopReason')?.value.trim();if(!reason){app.querySelector('#stopReason')?.reportValidity();return}state.windowStopped=true;go('live')}else if(a==='confirmCancel'){e.stopImmediatePropagation();state.booking.cancelled=true;go('cancelled')}else if(a==='visitDone'||a==='visitNoShow'){e.stopImmediatePropagation();state.visitResult=a==='visitDone'?'Визит завершён':'Неявка отмечена';render()}},true);
app.addEventListener('click',e=>{const el=e.target.closest('[data-action="period"],[data-action="searchService"]');if(!el)return;state[el.dataset.action]=el.dataset.value;render()});
app.addEventListener('click',e=>{const el=e.target.closest('[data-go][data-salon]');if(!el)return;state.salon=el.dataset.salon;if(el.dataset.service)state.service=el.dataset.service;if(el.dataset.staff)state.staff=el.dataset.staff;if(el.dataset.price)state.price=Number(el.dataset.price);if(el.dataset.slot)state.slot=el.dataset.slot;if(el.dataset.service)state.duration=60},true);
render();
function cLoyalty(){if(state.salon==='Линия')return loyalty();let s=hybridSalons.find(x=>x.name===state.salon)||hybridSalons[0];return heading('НАГРАДЫ / '+h(s.name).toUpperCase(),'Бонусы «'+h(s.name)+'»','Прогресс и награды относятся только к этому салону.')+note('Пока нет доступных наград','После визитов здесь появятся ваши бонусы.')+button('Посмотреть услуги','salon')+button('К моим местам','home','secondary')}
app.addEventListener('input',e=>{if(!e.target.matches('[data-place-search]'))return;state.query=e.target.value;let slot=app.querySelector('.c-results-slot');if(slot)slot.innerHTML=cSearchResults()});
app.addEventListener('input',e=>{if(!e.target.matches('[data-owner-staff-search]'))return;state.ownerStaffQuery=e.target.value;let options=app.querySelector('.owner-staff-options');if(options)options.innerHTML=ownerStaffOptions()});
app.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.ownerStaffOpen){state.ownerStaffOpen=false;render();app.querySelector('.owner-staff-trigger')?.focus()}});
app.addEventListener('click',e=>{if(e.target.closest('[data-action="clearSearch"]')){state.query='';render();return}let requested=e.target.closest('[data-theme]');if(requested){state.theme=requested.dataset.theme;localStorage.setItem('ryadom-theme',state.theme);render();return}});
function renderC(){app.innerHTML=`<div class="page theme-${state.theme}"><div class="lab"><header class="lab-head"><div><span class="label">РЯДОМ · MINI-APP ДЛЯ MAX</span><h1>Мои места</h1><p>Знакомый салон — в центре. Если хочется найти другой, ищите по названию, услуге или ключевым словам.</p></div><a class="link" href="about.html">О дизайне ↗</a></header>${sidebar()}<main class="stage"><div class="stage-top"><div><h2>${screens[state.screen]||'Обзор'}</h2><p>${state.role==='master'?'Планируйте месяц и открывайте свои записи по дням.':state.role==='client'?'Все визиты, услуги и награды — в контексте выбранного салона.':'Календарь, клиенты и лояльность вашего салона.'}</p></div><div class="stage-controls"><div class="view-mode" aria-label="Размер экрана"><button data-view="phone" class="${state.view==='phone'?'active':''}">Телефон</button><button data-view="desktop" class="${state.view==='desktop'?'active':''}">Компьютер</button></div><div class="mode"><button data-role="client" class="${state.role==='client'?'active':''}">Клиент</button><button data-role="owner" class="${state.role==='owner'?'active':''}">Владелец</button><button data-role="admin" class="${state.role==='admin'?'active':''}">Администратор</button><button data-role="master" class="${state.role==='master'?'active':''}">Мастер</button></div></div></div>${state.view==='phone'?`<div class="stage-body"><div class="device-wrap"><p class="device-label">MAX MINI-APP · 390 × 844</p><div class="device">${phone()}</div></div><aside class="explain"><span class="eyebrow">КОНЦЕПЦИЯ · МОИ МЕСТА</span><h3>Всё вокруг вашего салона</h3><p>Сначала знакомое место. Внутри — услуги, мастера, визиты и бонусы. Поиск помогает перейти к другому салону, не превращая главную в каталог фильтров.</p><div class="why journey"><h4>Быстрые маршруты</h4><button data-go="home">Моё место →</button><button data-go="discover">Поиск салона →</button><button data-go="bookings">Мои визиты →</button></div><p class="bottom-note">Демо с вымышленными данными. Записи и сообщения на сервере не создаются.</p></aside></div>`:desktopPreview()}</main></div></div>`;app.querySelector('.device .scroll')?.scrollTo(0,0)}
